class Solution:
    def matchReplacement(self, s: str, sub: str, mappings: List[List[str]]) -> bool:
        ok = [[False] * 128 for _ in range(128)]
        for c in range(128): ok[c][c] = True
        for a, b in mappings: ok[ord(a)][ord(b)] = True
        allowed = {}
        for j, ch in enumerate(sub):
            allowed[j] = [c for c in range(128) if ok[c][ord(ch)]]
        n, m = len(s), len(sub)
        for i in range(n - m + 1):
            if all(ord(s[i + j]) in allowed[j] for j in range(m)):
                return True
        return False

