class Solution:
    def matchReplacement(self, s: str, sub: str, mappings: List[List[str]]) -> bool:
        ok = [[False]*128 for _ in range(128)]
        for c in range(128): ok[c][c] = True
        for a, b in mappings: ok[ord(a)][ord(b)] = True
        pos = {c: [] for c in range(128)}
        for i, ch in enumerate(s): pos[ord(ch)].append(i)
        sets = [{c for c in range(128) if ok[c][ord(ch)]} for ch in sub]
        j0 = min(range(len(sub)), key=lambda j: sum(len(pos[c]) for c in sets[j]))
        cands = [i - j0 for c in sets[j0] for i in pos[c]]
        for st in set(cands):
            if st < 0 or st + len(sub) > len(s): continue
            if all(ord(s[st + j]) in sets[j] for j in range(len(sub))):
                return True
        return False

