// rarest sub position, then verify. Worst case still O(|s|*|sub|).
class Solution {
public:
    bool matchReplacement(string s, string sub, vector<vector<char>>& mappings) {
        bool ok[128][128] = {};
        for (int c = 0; c < 128; c++) ok[c][c] = true;
        for (auto& mp : mappings) ok[(int)mp[0]][(int)mp[1]] = true;
        int n = s.size(), m = sub.size();
        for (int i = 0; i + m <= n; i++) {
            bool good = true;
            for (int j = 0; j < m && good; j++) good = ok[(int)s[i+j]][(int)sub[j]];
            if (good) return true;
        }
        return false;
    }
};

